#  if a provider is installed, remove it
is_virtual=`apt-cache showpkg "ufw" | grep -Pzc 'Versions: \n\n'`
if [ $is_virtual = 1 ]; then
    rprovides_line=`apt-cache showpkg "ufw" | grep -n 'Reverse Provides:' | cut -f1 -d:`
